practice_questions.solution:
def count_delayed(staff_members, staff_id):
    count = 0
    for person in staff_members:
        if person.identifier == staff_id:
            for project in person.projects:
                if project is not None and project.days > 45 and project.decision == "N":
                    count += 1
            return count
    return 0

